package com.kafka.backend.shareddesk;
import com.kafka.backend.shareddesk.storage.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import tools.jackson.databind.json.JsonMapper;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

/** Real PostgreSQL fixtures in a disposable loopback-only database, never shared DEV/PROD. */
@EnabledIfEnvironmentVariable(named="SHARED_DESK_TEST_DB",matches="jdbc:postgresql://127\\.0\\.0\\.1:55487/postgres")
class DeskServicePostgresTest {
 JdbcTemplate db;DeskService service,other;DeskFiles files;UUID a=UUID.randomUUID(),b=UUID.randomUUID();
 ObjectStorage off=new ObjectStorage(){public boolean enabled(){return false;}public String newStagingKey(UUID o){throw new UnsupportedOperationException();}public String newFinalKey(UUID o){throw new UnsupportedOperationException();}public SignedTicket presignPut(UUID o,String k,FilePolicy.Claim c){throw new UnsupportedOperationException();}public FilePolicy.Verified promoteAndVerify(UUID o,String a,String b,FilePolicy.Claim c){throw new UnsupportedOperationException();}public SignedTicket presignGet(UUID o,String k,String n){throw new UnsupportedOperationException();}public void delete(UUID o,String k){throw new UnsupportedOperationException();}};
 @BeforeEach void setup()throws Exception{
  var ds=new DriverManagerDataSource(System.getenv("SHARED_DESK_TEST_DB"),"desk_test","");db=new JdbcTemplate(ds);
  db.execute("drop schema if exists desk_test cascade");db.execute("create schema desk_test");db.execute("create schema if not exists auth");db.execute("create table if not exists auth.users(id uuid primary key)");
  // Each connection receives the isolated schema. auth is a local fixture schema only.
  ds.setUrl(System.getenv("SHARED_DESK_TEST_DB")+"?currentSchema=desk_test,public");
  db.execute("create table projects(id uuid primary key,user_id uuid not null,name text)");db.update("insert into auth.users(id) values(?),(?)",a,b);
  db.execute(Files.readString(Path.of("src/main/resources/db/migration/V101__shared_desk_v1.sql")));
  var manager=new DataSourceTransactionManager(ds);var json=JsonMapper.builder().build();service=new DeskService(db,()->a,json,manager,off,true,"TEST");other=new DeskService(db,()->b,json,manager,off,true,"TEST");files=new DeskFiles(service,off);
 }
 Map<String,Object> op(Object... values){var m=new LinkedHashMap<String,Object>();m.put("operationId",UUID.randomUUID().toString());m.put("operationCreatedAt",Instant.now().toString());for(int i=0;i<values.length;i+=2)m.put(values[i].toString(),values[i+1]);return m;}
 UUID id(Map<String,Object> m){return UUID.fromString(m.get("id").toString());}
 void fails(int status,Runnable r){assertThatThrownBy(r::run).isInstanceOfSatisfying(DeskException.class,e->assertThat(e.status).isEqualTo(status));}
 @Test void exactTextAndOwnerIsolation(){String body="한글\n\n```json\n{\"a\":1}\n```\n";var x=service.create("CLIP",op("body",body));assertThat(service.get("CLIP",id(x)).get("body")).isEqualTo(body);assertThat(other.list("CLIP","",null,false,null,50,false).get("items")).asList().isEmpty();fails(404,()->other.get("CLIP",id(x)));fails(404,()->other.patch("CLIP",id(x),op("expectedRevision",1,"body","illegal")));fails(404,()->other.delete("CLIP",id(x),op("expectedRevision",1)));fails(404,()->other.restore(id(x),op("expectedRevision",1)));}
 @Test void operationReplayConflictAndExpiry(){var request=op("body","same");var x=service.create("CLIP",request);assertThat(service.create("CLIP",request)).containsEntry("id",x.get("id").toString());var changed=new LinkedHashMap<>(request);changed.put("body","different");fails(409,()->service.create("CLIP",changed));db.update("update shared_desk_operations set expires_at=current_timestamp-interval '1 second'");fails(410,()->service.create("CLIP",request));var old=op("body","old");old.put("operationCreatedAt",Instant.now().minus(Duration.ofDays(31)).toString());fails(410,()->service.create("CLIP",old));}
 @Test void casAndRequiredRevision(){var x=service.create("CLIP",op("body","original"));fails(428,()->service.patch("CLIP",id(x),op("body","bad")));service.patch("CLIP",id(x),op("expectedRevision",1,"body","winner"));fails(409,()->service.patch("CLIP",id(x),op("expectedRevision",1,"body","loser")));assertThat(service.get("CLIP",id(x)).get("body")).isEqualTo("winner");}
 @Test void projectForeignKeyAndDeletionPreserveContent(){UUID p=UUID.randomUUID();db.update("insert into projects values(?,?,?)",p,a,"synthetic");var clip=service.create("CLIP",op("body","keep","projectId",p.toString()));fails(404,()->other.create("CLIP",op("body","x","projectId",p.toString())));assertThatThrownBy(()->db.update("update shared_desk_items set owner_id=? where id=?",b,id(clip))).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);db.update("delete from projects where id=?",p);assertThat(service.get("CLIP",id(clip))).containsEntry("projectId",null).containsEntry("body","keep");}
 @Test void memoRepliesDeleteRestoreAndWrongParent(){var memo=service.create("MEMO",op("body","root"));service.reply(id(memo),op("body","reply\n"));var current=service.get("MEMO",id(memo));service.delete("MEMO",id(memo),op("expectedRevision",current.get("revision")));fails(410,()->service.reply(id(memo),op("body","late")));fails(404,()->other.replies(id(memo)));service.restore(id(memo),op("expectedRevision",3));assertThat(service.replies(id(memo))).hasSize(1);var clip=service.create("CLIP",op("body","clip"));fails(404,()->service.reply(id(clip),op("body","wrong")));}
 @Test void stablePaginationSurvivesMutations(){var one=service.create("CLIP",op("body","one"));service.create("CLIP",op("body","two"));var first=service.list("CLIP","",null,false,null,1,false);String cursor=first.get("nextCursor").toString();service.patch("CLIP",id(one),op("expectedRevision",1,"body","moved"));service.create("CLIP",op("body","third"));var second=service.list("CLIP","",null,false,cursor,1,false);assertThat(second.get("items").toString()).contains("one").doesNotContain("moved","third");fails(400,()->other.list("CLIP","",null,false,cursor,1,false));fails(400,()->service.list("CLIP","filter",null,false,cursor,1,false));db.update("update shared_desk_cursors set expires_at=current_timestamp-interval '1 second' where token=?",UUID.fromString(cursor));fails(410,()->service.list("CLIP","",null,false,cursor,1,false));}
 @Test void changesBoundedHighWaterAndCrossOwnerCursor(){String after=service.changes(null,null,100).get("nextCursor").toString();service.create("CLIP",op("body","a"));service.create("MEMO",op("body","b"));var first=service.changes(after,null,1);service.create("CLIP",op("body","later"));var second=service.changes(first.get("nextCursor").toString(),first.get("highWater").toString(),100);assertThat(second.get("changes")).asList().hasSize(1);fails(400,()->other.changes(after,null,100));}
 @Test void concurrentIdempotentCreatesCommitOnce()throws Exception{var request=op("body","once");var pool=Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(List.<Callable<Map<String,Object>>>of(()->service.create("CLIP",request),()->service.create("CLIP",request)));assertThat(results.get(0).get().get("id").toString()).isEqualTo(results.get(1).get().get("id").toString());assertThat(db.queryForObject("select count(*) from shared_desk_items",Integer.class)).isEqualTo(1);assertThat(db.queryForObject("select last_seq from shared_desk_sync_heads where owner_id=?",Long.class,a)).isEqualTo(1L);}finally{pool.shutdownNow();}}
 @Test void textLimitAndStorageFailureDoesNotBreakText(){fails(413,()->service.create("CLIP",op("body","가".repeat(349526))));fails(503,()->files.create(op("displayName","x.txt","sizeBytes",1,"sha256","0".repeat(64),"claimedMime","text/plain")));assertThat(service.create("CLIP",op("body","still works"))).containsEntry("body","still works");}
 @Test void validCursorCannotSkipPurgedSequencePrefix(){String after=service.changes(null,null,10).get("nextCursor").toString();service.create("CLIP",op("body","old"));service.create("MEMO",op("body","new"));db.update("update shared_desk_changes set created_at=current_timestamp-interval '31 days' where seq=1");new DeskMaintenance(service,files).sweep();fails(410,()->service.changes(after,null,10));assertThat(service.changes(null,null,10).get("changes")).asList().isEmpty();}
 @Test void replyPaginationPreservesSnapshot(){var memo=service.create("MEMO",op("body","root"));service.reply(id(memo),op("body","first"));service.reply(id(memo),op("body","second"));var first=service.replyPage(id(memo),null,1);service.reply(id(memo),op("body","third"));var second=service.replyPage(id(memo),first.get("nextCursor").toString(),1);assertThat(second.get("items").toString()).contains("second").doesNotContain("third");}
 @Test void trashExpiryAndCleanupPreserveLiveData(){var deleted=service.create("MEMO",op("body","remove"));service.reply(id(deleted),op("body","child"));service.delete("MEMO",id(deleted),op("expectedRevision",2));var live=service.create("CLIP",op("body","preserve"));db.update("update shared_desk_items set deleted_at=current_timestamp-interval '8 days' where id=?",id(deleted));fails(410,()->service.restore(id(deleted),op("expectedRevision",3)));new DeskMaintenance(service,files).sweep();fails(404,()->service.get("MEMO",id(deleted)));assertThat(service.get("CLIP",id(live))).containsEntry("body","preserve");assertThat(db.queryForObject("select count(*) from shared_desk_replies",Integer.class)).isZero();}
}
